def _parse_aot(self, first, name_first):  # type: (Table, str) -> AoT
        """
        Parses all siblings of the provided table first and bundles them into
        an AoT.
        """
        if first.name == name_first:
            return AoT(first)

        siblings = [first]
        while True:
            next_ = first.next_sibling
            if next_ is None:
                break
            siblings.append(next_)
            first = next_

        return AoT(siblings)

